-- توسيمُ مواضعِ الاقتباسات القرآنية في `qa_questions` — الدفعةُ الثانية:
-- صفوفٌ حجبها عن الدفعة الأولى **انتقاءٌ بالصفّ لا بالمقتبس** (كان الصفُّ
-- يُؤجَّل كلُّه إن جاور فيه مقتبسٌ مبهَمٌ مقتبساتٍ ثابتة)، فأُصلح الانتقاءُ
-- في scripts/locate-quran-quotes.py: يُوسَم ما ثبت بمقابلة المصحف، ويبقى
-- المبهَمُ بلا وسمٍ ولا يُخترَع له ترجيح.
-- النصُّ كاملٌ لكلِّ صفّ ⇒ إعادةُ التشغيل لا تُغيِّر شيئًا.
BEGIN;
-- (١) الحقل evidence — صفٌّ واحد
UPDATE qa_questions SET evidence = '﴿ٱدْعُ إِلَىٰ سَبِيلِ رَبِّكَ بِٱلْحِكْمَةِ وَٱلْمَوْعِظَةِ ٱلْحَسَنَةِ ۖ وَجَٰدِلْهُم بِٱلَّتِى هِىَ أَحْسَنُ﴾ [النحل: ١٢٥]. قال الطبريُّ في تأويلها: «ادْعُ يا محمدُ من أرْسَلك إليه ربُّك بالدعاءِ إلى طاعتِه، ﴿إِلَى سَبِيلِ رَبِّكَ﴾ [النحل: ١٢٥]. يقولُ: إلى شريعةِ ربِّك التي شرَعَها لخلقِه، وهو الإسلامُ، ﴿بِالْحِكْمَةِ﴾. يقولُ: بوحيِ اللهِ الذى يُوحِيه إليك، وكتابِه الذي يُنْزِلُه عليك، ﴿وَالْمَوْعِظَةِ الْحَسَنَةِ﴾ [النحل: ١٢٥]. يقولُ: وبالعِبَرِ الجميلةِ التي جعَلها اللهُ حُجَّةً عليهم في كتابِه»، ثم قال في ﴿وَجَٰدِلْهُم بِٱلَّتِى هِىَ أَحْسَنُ﴾ [النحل: ١٢٥]: «يقولُ: وخاصِمْهم بالخصومةِ التي هي أحسنُ من غيرِها؛ أن تَصْفَحَ عما نالوا به عِرْضَك من الأذى» (ج١٤/ص٤٠٠).'
  WHERE id = 'f051352e-d318-4905-973b-6376946d7875';
-- (٢) الحقل answer — ٣ صفوف
UPDATE qa_questions SET answer = 'أذكارُ النوم ثابتةٌ في الصحيحين بألفاظها ومواضعها؛ وأجمعُها ما يلي: (١) **آيةُ الكرسيّ**؛ قال النبيُّ ﷺ: «إِذَا أَوَيْتَ إِلَى فِرَاشِكَ فَاقْرَأْ آيَةَ الْكُرْسِيِّ ﴿اللهُ لا إِلَهَ إِلا هُوَ الْحَيُّ الْقَيُّومُ﴾ حَتَّى تَخْتِمَ الْآيَةَ فَإِنَّكَ لَنْ يَزَالَ عَلَيْكَ مِنَ اللهِ حَافِظٌ وَلَا يَقْرَبَنَّكَ شَيْطَانٌ حَتَّى تُصْبِحَ» (رواه البخاري). (٢) **المعوِّذاتُ**، وهي ثلاثٌ لا اثنتان؛ قالت عائشة رضي الله عنها: إنّ النبيّ ﷺ «كَانَ إِذَا أَوَى إِلَى فِرَاشِهِ كُلَّ لَيْلَةٍ، جَمَعَ كَفَّيْهِ ثُمَّ نَفَثَ فِيهِمَا، فَقَرَأَ فِيهِمَا: ﴿قُلْ هُوَ اللهُ أَحَدٌ﴾ [الإخلاص: ١]، وَ ﴿قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ﴾ [الفلق: ١]، وَ ﴿قُلْ أَعُوذُ بِرَبِّ النَّاسِ﴾ [الناس: ١]، ثُمَّ يَمْسَحُ بِهِمَا مَا اسْتَطَاعَ مِنْ جَسَدِهِ، يَبْدَأُ بِهِمَا عَلَى رَأْسِهِ وَوَجْهِهِ، وَمَا أَقْبَلَ مِنْ جَسَدِهِ، يَفْعَلُ ذَلِكَ ثَلَاثَ مَرَّاتٍ» (رواه البخاري). (٣) **آخرُ آيتين من سورة البقرة**؛ قال ﷺ: «مَنْ قَرَأَ بِالْآيَتَيْنِ مِنْ آخِرِ سُورَةِ الْبَقَرَةِ فِي لَيْلَةٍ كَفَتَاهُ» (رواه البخاري). (٤) **التسبيحُ والتحميدُ والتكبير** عند المضجع، وهو الذي علّمه النبيُّ ﷺ فاطمةَ وعليًّا رضي الله عنهما حين سألته خادمًا: «أَلَا أَدُلُّكُمَا عَلَى مَا هُوَ خَيْرٌ لَكُمَا مِنْ خَادِمٍ»؛ وقد اختلف لفظُ الروايتين في موضع الزيادة، فعند البخاري: «إِذَا أَوَيْتُمَا إِلَى فِرَاشِكُمَا أَوْ أَخَذْتُمَا مَضَاجِعَكُمَا فَكَبِّرَا ثَلَاثًا وَثَلَاثِينَ، وَسَبِّحَا ثَلَاثًا وَثَلَاثِينَ، وَاحْمَدَا ثَلَاثًا وَثَلَاثِينَ»، وفي آخر الموضع نفسِه عن ابن سيرين: «التَّسْبِيحُ أَرْبَعٌ وَثَلَاثُونَ»؛ وعند مسلم: «إذا أخذتما مضاجعكما، أن تكبرا الله أربعا وثلاثين. وتسبحاه ثلاثا وثلاثين. وتحمداه ثلاثا وثلاثين. فهو خير لكما من خادم» — فالمجموعُ مائةٌ في الروايتين جميعًا، وإنما اختلفتا في التي تُزاد فيها الواحدة. (٥) **دعاءُ الاضطجاع**، وهو أجمعُها؛ قال ﷺ للبراء بن عازب رضي الله عنه: «إِذَا أَتَيْتَ مَضْجَعَكَ فَتَوَضَّأْ وُضُوءَكَ لِلصَّلَاةِ، ثُمَّ اضْطَجِعْ عَلَى شِقِّكَ الْأَيْمَنِ، ثُمَّ قُلِ: اللَّهُمَّ أَسْلَمْتُ وَجْهِي إِلَيْكَ، وَفَوَّضْتُ أَمْرِي إِلَيْكَ، وَأَلْجَأْتُ ظَهْرِي إِلَيْكَ، رَغْبَةً وَرَهْبَةً إِلَيْكَ، لَا مَلْجَأَ وَلَا مَنْجَا مِنْكَ إِلَّا إِلَيْكَ، اللَّهُمَّ آمَنْتُ بِكِتَابِكَ الَّذِي أَنْزَلْتَ، وَبِنَبِيِّكَ الَّذِي أَرْسَلْتَ. فَإِنْ مُتَّ مِنْ لَيْلَتِكَ، فَأَنْتَ عَلَى» الفطرة، وأمرَه أن يجعلهنّ خاتمةَ كلامه: «وَاجْعَلْهُنَّ آخِرَ مَا تَتَكَلَّمُ بِهِ» (رواه البخاري). وفي هذا الحديث أصلٌ في **لزوم اللفظ المأثور** كما ورد؛ قال البراء: «فَرَدَّدْتُهَا عَلَى النَّبِيِّ ﷺ ، فَلَمَّا بَلَغْتُ: اللَّهُمَّ آمَنْتُ بِكِتَابِكَ الَّذِي أَنْزَلْتَ، قُلْتُ: وَرَسُولِكَ، قَالَ: لَا، وَنَبِيِّكَ الَّذِي أَرْسَلْتَ». (٦) وآخرُ ما يقولُه عند إرادة النوم: «بِاسْمِكَ اللَّهُمَّ أَمُوتُ وَأَحْيَا»، فإذا استيقظ قال: «الْحَمْدُ لِلهِ الَّذِي أَحْيَانَا بَعْدَمَا أَمَاتَنَا وَإِلَيْهِ النُّشُورُ» (رواه البخاري).'
  WHERE id = '15d97eaa-b63d-4634-8651-0f3742cf1431';
UPDATE qa_questions SET answer = 'سُميت بذلك لأن أحزابًا من العرب واليهود تحزَّبت مجتمعةً على النبي صلى الله عليه وسلم لحصار المدينة، وهو نصُّ ابن إسحاق في نفَرٍ من يهود بني النضير وبني وائل قدِموا مكة يدعون قريشًا إلى حربه: «وَهُمْ الَّذِينَ حَزَّبُوا الْأَحْزَابَ عَلَى رَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ»؛ فخرجت قريش وقائدها أبو سفيان بن حرب، وغطفان وقائدها عيينة بن حصن في بني فزارة، والحارث بن عوف المرّي في بني مرة، ومسعر بن رخيلة فيمن تابعه من أشجع. وبها سمّاهم القرآن ﴿جُنُودٌۭ﴾ في قوله: ﴿ٱذْكُرُوا۟ نِعْمَةَ ٱللَّهِ عَلَيْكُمْ إِذْ جَآءَتْكُمْ جُنُودٌۭ فَأَرْسَلْنَا عَلَيْهِمْ رِيحًۭا وَجُنُودًۭا لَّمْ تَرَوْهَا﴾ [الأحزاب: ٩] ﴿إِذْ جَآءُوكُم مِّن فَوْقِكُمْ وَمِنْ أَسْفَلَ مِنكُمْ﴾ [الأحزاب: ٩-١٠]. وتُسمَّى غزوة الخندق كذلك، وكانت «فِي شَوَّالٍ سَنَةَ خَمْسٍ»، لأن النبي صلى الله عليه وسلم «ضَرَبَ الْخَنْدَقَ عَلَى الْمَدِينَةِ، فَعَمِلَ فِيهِ ... تَرْغِيبًا لِلْمُسْلِمِينَ فِي الْأَجْرِ، وَعَمِلَ مَعَهُ الْمُسْلِمُونَ فِيهِ». وأما نسبةُ المشورة بحفره إلى سلمان الفارسي رضي الله عنه فقد ذكرها ابن هشام بصيغة التمريض لا بالجزم: «يُقَالُ: إنَّ سَلْمَانَ الْفَارِسِيَّ أَشَارَ بِهِ عَلَى رَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ».'
  WHERE id = '7d8a6cc6-492f-4a45-be25-57080f815cdf';
UPDATE qa_questions SET answer = 'هما مصطلحان متمايزان لا مصطلح واحد، ونصُّ السيوطي في الإتقان يفصل بينهما: «فالوجوه للفظ المشترك الذي يُستعمل في عدة معانٍ كلفظ الأمة… والنظائر كالألفاظ المتواطئة»؛ فالوجوهُ تعدُّدُ معاني اللفظ الواحد بحسب سياقاته، والنظائرُ الألفاظُ المتواطئةُ التي يجمعها معنًى واحد في مواضع كثيرة. ومثالُ الوجوه لفظُ «الهدى» — قال السيوطي: «يأتي على تسعة عشر وجهًا»، منها الثبات في ﴿اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ﴾ [ٱلفاتحة: ٦]، والبيان في ﴿أُولَئِكَ عَلَى هُدًى مِنْ رَبِّهِمْ﴾، والدين في ﴿إِنَّ الْهُدَى هُدَى اللَّهِ﴾ [ال عمران: ٧٣]، والإيمان في ﴿وَيَزِيدُ اللَّهُ الَّذِينَ اهْتَدَوْا هُدًى﴾ [مريم: ٧٦]. وأولُ من صنَّف فيه مقاتل بن سليمان، ثم ابن الجوزي وابن الدامغاني وابن فارس وغيرهم، وقد عدَّه بعضهم من أنواع إعجاز القرآن «حيث كانت الكلمة الواحدة تنصرف إلى عشرين وجهًا وأكثر وأقلّ ولا يوجد ذلك في كلام البشر».'
  WHERE id = 'd09d91d4-66b1-4c5c-8cee-819156b8607a';
COMMIT;
